mapper.select:
SELECT , sys_dept.dept_name AS deptName, EXISTS ( SELECT 1 FROM sys_user_role AS delivery_user_role INNER JOIN sys_role AS delivery_role ON delivery_role.id = delivery_user_role.role_id AND delivery_role.del_flag = '0' AND delivery_role.role_code = 'delivery_staff' WHERE delivery_user_role.del_flag = '0' AND delivery_user_role.user_id = sys_user.id AND delivery_user_role.tenant_id = sys_user.tenant_id AND delivery_role.tenant_id = sys_user.tenant_id ) AS deliveryQualification FROM sys_user AS sys_user LEFT JOIN sys_dept AS sys_dept ON sys_user.dept_id = sys_dept.id
AND sys_user.del_flag = '0'
AND sys_user.username =#{query.username}
AND sys_user.phone =#{query.phone}
AND sys_user.dept_id =#{query.deptId}

SELECT COUNT( 1 ) FROM `sys_user` AS sys_user
AND sys_user.del_flag = '0'
AND sys_user.`phone` =#{query.phone}

SELECT sys_user.id,
       sys_user.nickname,
       sys_user.avatar,
       sys_user.dept_id
FROM sys_user
WHERE sys_user.tenant_id = #{query.tenantId}
  AND sys_user.del_flag = '0'
  AND sys_user.status = '0'

    AND sys_user.id > #{query.cursor}


    AND sys_user.id IN

        #{userId}



    AND sys_user.dept_id IN

        #{deptId}



    AND EXISTS (
        SELECT 1 FROM sys_user_role
        WHERE sys_user_role.tenant_id = #{query.tenantId}
          AND sys_user_role.del_flag = '0'
          AND sys_user_role.user_id = sys_user.id
          AND sys_user_role.role_id IN

            #{roleId}

    )


    AND EXISTS (
        SELECT 1
        FROM sys_user_role AS sys_user_role
        INNER JOIN sys_role_menu AS sys_role_menu ON sys_role_menu.tenant_id = #{query.tenantId}
            AND sys_role_menu.role_id = sys_user_role.role_id
        INNER JOIN sys_menu ON sys_menu.id = sys_role_menu.menu_id
            AND sys_menu.del_flag = '0'
        WHERE sys_user_role.tenant_id = #{query.tenantId}
          AND sys_user_role.del_flag = '0'
          AND sys_user_role.user_id = sys_user.id
          AND sys_menu.permission IN ('message:service:agent', 'message:service:supervisor')
    )

ORDER BY sys_user.id ASC
LIMIT #{fetchSize}
